import { ArgumentParser } from './lib/argparse.mjs';
import { parsePythonInt } from './lib/pyint.mjs';
import { parsePythonFloat } from './lib/pyfloat.mjs';
import { encodeCanonicalJson, encodePrettyPrintedJson, iterencodeCanonicalJson } from './lib/canonicaljson.mjs';
import { pythonBytesRepr } from './lib/pybytes.mjs';

const parser = new ArgumentParser({ prog: process.argv[1].split('/').pop() });
parser.addArgument('--a', { typeName: 'str', required: true });
parser.addArgument('--b', { type: parsePythonInt, typeName: 'int', required: true });
parser.addArgument('--c', { type: parsePythonFloat, typeName: 'float', required: true });
const args = parser.parseArgs(process.argv.slice(2));

const data = {
  string: args.a,
  integer: args.b,
  float: args.c,
  list: [args.a, args.b, args.c],
};

try {
  const canonicalBytes = encodeCanonicalJson(data);
  const prettyBytes = encodePrettyPrintedJson(data);
  const chunks = [...iterencodeCanonicalJson(data)];
  console.log(pythonBytesRepr(canonicalBytes));
  console.log(pythonBytesRepr(prettyBytes));
  console.log(chunks.length);
} catch (err) {
  if (err.name === 'ValueError') {
    process.stderr.write('ValueError: ' + err.message + '\n');
    process.exit(1);
  }
  throw err;
}

