// Python int(str) (base 10) emulation and repr for BigInt values.

const ASCII_WHITESPACE = ' \t\n\r\f\v';

function valueError() {
  const err = new Error('invalid literal for int() with base 10');
  err.name = 'ValueError';
  return err;
}

export function parsePythonInt(str) {
  if (typeof str !== 'string') {
    throw valueError();
  }

  // Strip leading/trailing ASCII whitespace.
  let start = 0;
  let end = str.length;
  while (start < end && ASCII_WHITESPACE.includes(str[start])) start++;
  while (end > start && ASCII_WHITESPACE.includes(str[end - 1])) end--;
  const s = str.slice(start, end);

  if (s.length === 0) {
    throw valueError();
  }

  let i = 0;
  let negative = false;
  if (s[i] === '+' || s[i] === '-') {
    negative = s[i] === '-';
    i++;
  }

  const digits = s.slice(i);
  // One or more digits; single underscores only between two digits.
  if (!/^[0-9](?:_?[0-9])*$/.test(digits)) {
    throw valueError();
  }

  const cleaned = digits.replace(/_/g, '');
  const value = BigInt(cleaned);
  return negative ? -value : value;
}

export function reprPythonInt(value) {
  return value.toString();
}

