// Mimics CPython's json module encode_basestring (json.dumps with
// ensure_ascii=False): wrap in double quotes, escape the standard set,
// \u00xx for other control chars below 0x20, pass everything else through.

const ESCAPE_MAP = new Map([
  [0x22, '\\"'],
  [0x5c, '\\\\'],
  [0x08, '\\b'],
  [0x0c, '\\f'],
  [0x0a, '\\n'],
  [0x0d, '\\r'],
  [0x09, '\\t'],
]);

export function escapeJsonString(s) {
  let out = '"';
  for (const ch of s) {
    const code = ch.codePointAt(0);
    const mapped = ESCAPE_MAP.get(code);
    if (mapped !== undefined) {
      out += mapped;
    } else if (code < 0x20) {
      out += '\\u' + code.toString(16).padStart(4, '0');
    } else {
      out += ch;
    }
  }
  return out + '"';
}

