// pybytes.mjs — helpers mimicking Python bytes behavior.

/**
 * Encode a JS string into a Uint8Array of UTF-8 bytes.
 * @param {string} str
 * @returns {Uint8Array}
 */
export function utf8Encode(str) {
  return new TextEncoder().encode(str);
}

/**
 * Return a JS string that exactly mimics CPython's repr() of a bytes object.
 * @param {Uint8Array} bytes
 * @returns {string}
 */
export function pythonBytesRepr(bytes) {
  let hasSingle = false;
  let hasDouble = false;
  for (const b of bytes) {
    if (b === 0x27) hasSingle = true;
    else if (b === 0x22) hasDouble = true;
  }
  // Use single quote unless there is a ' and no " present.
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const quoteCode = quote.charCodeAt(0);

  let out = 'b' + quote;
  for (const b of bytes) {
    if (b === quoteCode || b === 0x5c) {
      out += '\\' + String.fromCharCode(b);
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b < 0x20 || b >= 0x7f) {
      out += '\\x' + b.toString(16).padStart(2, '0');
    } else {
      out += String.fromCharCode(b);
    }
  }
  out += quote;
  return out;
}

