// Python float parsing and repr helpers.
// Python float <-> JS Number (IEEE 754 double).

const FLOAT_WS = /^[ \t\n\r\f\v]+|[ \t\n\r\f\v]+$/g;

// A digit run with optional single underscores strictly between digits.
const DIGITS = '\\d(?:_?\\d)*';
const DECIMAL_RE = new RegExp(
  '^[+-]?(?:' + DIGITS + '(?:\\.(?:' + DIGITS + ')?)?|\\.' + DIGITS + ')' +
  '(?:[eE][+-]?' + DIGITS + ')?$'
);
const SPECIAL_RE = /^([+-]?)(inf(?:inity)?|nan)$/i;

function valueError() {
  const err = new Error('could not convert string to float');
  err.name = 'ValueError';
  return err;
}

// Mimic Python's built-in float(str).
export function parsePythonFloat(str) {
  const s = String(str).replace(FLOAT_WS, '');

  const special = SPECIAL_RE.exec(s);
  if (special) {
    const neg = special[1] === '-';
    const word = special[2].toLowerCase();
    if (word === 'nan') return NaN;
    return neg ? -Infinity : Infinity;
  }

  if (!DECIMAL_RE.test(s)) throw valueError();
  return Number(s.replace(/_/g, ''));
}

// Mimic CPython repr(float): shortest round-trip representation.
export function reprPythonFloat(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';
  if (x === 0) return Object.is(x, -0) ? '-0.0' : '0.0';

  const neg = x < 0;
  const a = neg ? -x : x;

  // Shortest digit string that round-trips.
  let s;
  for (let p = 1; p <= 17; p++) {
    s = a.toPrecision(p);
    if (Number(s) === a) break;
  }

  // Parse s (fixed or exponential) into digits/decpt with
  // value = 0.digits * 10^decpt.
  let mantissa = s;
  let exp = 0;
  const eIdx = s.indexOf('e');
  if (eIdx !== -1) {
    mantissa = s.slice(0, eIdx);
    exp = Number(s.slice(eIdx + 1));
  }
  const dotIdx = mantissa.indexOf('.');
  const pointPos = dotIdx === -1 ? mantissa.length : dotIdx;
  let digits = mantissa.replace('.', '');
  let decpt = pointPos + exp;

  // Strip leading zeros (each shifts decpt down by one).
  let lead = 0;
  while (lead < digits.length - 1 && digits[lead] === '0') lead++;
  digits = digits.slice(lead);
  decpt -= lead;
  // Strip trailing zeros.
  digits = digits.replace(/0+$/, '');

  let out;
  if (decpt > 16 || decpt <= -4) {
    const e = decpt - 1;
    out = digits[0];
    if (digits.length > 1) out += '.' + digits.slice(1);
    out += 'e' + (e < 0 ? '-' : '+') + String(Math.abs(e)).padStart(2, '0');
  } else if (decpt <= 0) {
    out = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    out = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }

  return neg ? '-' + out : out;
}

