// Black-box reimplementation of the Python `canonicaljson` package.
// Reproduces the chunk boundaries of CPython's pure-Python
// json.encoder._make_iterencode (ensure_ascii=False, sort_keys=True).

import { escapeJsonString } from './pyescape.mjs';
import { reprPythonFloat } from './pyfloat.mjs';
import { utf8Encode } from './pybytes.mjs';

// Compare strings by Unicode code point (not UTF-16 code unit).
function compareKeysByCodePoint(a, b) {
    const ca = Array.from(a);
    const cb = Array.from(b);
    const n = Math.min(ca.length, cb.length);
    for (let i = 0; i < n; i++) {
        const pa = ca[i].codePointAt(0);
        const pb = cb[i].codePointAt(0);
        if (pa !== pb) {
            return pa - pb;
        }
    }
    return ca.length - cb.length;
}

function rejectBadFloat(x) {
    if (Number.isNaN(x) || !Number.isFinite(x)) {
        const err = new Error(
            'Out of range float values are not JSON compliant: ' + reprPythonFloat(x)
        );
        err.name = 'ValueError';
        throw err;
    }
}

function* dictEncode(obj, level, indent, itemSeparator, keySeparator) {
    const keys = Object.keys(obj);
    if (keys.length === 0) {
        yield '{}';
        return;
    }
