// Minimal ES-module clone of Python's argparse.
// Pure JavaScript, no imports, no JSON.stringify/parse.

const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

function defaultProg() {
  // Mimic argparse's default: basename of sys.argv[0] (here process.argv[1]).
  const argv1 = process.argv && process.argv[1];
  if (!argv1) return 'program';
  const parts = argv1.split(/[\\/]/);
  return parts[parts.length - 1] || 'program';
}

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog !== undefined ? prog : defaultProg();
    // Declared options in declaration order.
    // Each: { name, dest, type, typeName, required, metavar }
    this._options = [];
  }

  addArgument(name, { type = (s) => s, typeName = 'str', required = false, metavar } = {}) {
    const dest = name.replace(/^-+/, '');
    const mv = metavar !== undefined ? metavar : dest.toUpperCase();
    this._options.push({ name, dest, type, typeName, required, metavar: mv });
  }

  _usageLine() {
    let line = 'usage: ' + this.prog + ' [-h]';
    for (const opt of this._options) {
      line += opt.required ? ` ${opt.name} ${opt.metavar}` : ` [${opt.name} ${opt.metavar}]`;
    }
    return line;
  }

  _helpText() {
    let text = this._usageLine() + '\n\noptions:\n';
    text += '  -h, --help  show this help message and exit\n';
    for (const opt of this._options) {
      text += `  ${opt.name} ${opt.metavar}\n`;
    }
    return text;
  }

  _fail(message) {
    process.stderr.write(this._usageLine() + '\n');
    process.stderr.write(this.prog + ': error: ' + message + '\n');
    process.exit(2);
  }

  _printHelpAndExit() {
    process.stdout.write(this._helpText());
    process.exit(0);
  }

  // Resolve an option name (without any '=value' part) to a canonical name.
  // Returns { kind: 'help' } or { kind: 'option', option } or
  // { kind: 'unknown' } or { kind: 'ambiguous', matches }.
  _resolveName(tokenName) {
    if (tokenName === '-h' || tokenName === '--help') {
      return { kind: 'help' };
    }
    for (const opt of this._options) {
      if (opt.name === tokenName) {
        return { kind: 'option', option: opt };
      }
    }
    // Unique prefix abbreviation of a known long option (allow_abbrev).
    if (tokenName.startsWith('--') && tokenName.length > 2) {
      const matches = [];
      if ('--help'.startsWith(tokenName)) matches.push('--help');
      for (const opt of this._options) {
        if (opt.name.startsWith(tokenName)) matches.push(opt.name);
