        const name = matches[0];
        if (name === '--help') return { kind: 'help' };
        const option = this._options.find((o) => o.name === name);
        return { kind: 'option', option };
      }
      if (matches.length > 1) {
        return { kind: 'ambiguous', matches };
      }
    }
    return { kind: 'unknown' };
  }

  parseArgs(argv) {
    const values = {};
    const seen = new Set();
    const extras = [];
    let afterDoubleDash = false;

    let i = 0;
    while (i < argv.length) {
      const token = argv[i];
      i += 1;

      if (afterDoubleDash) {
