      const resolved = this._resolveName(tokenName);

      if (resolved.kind === 'help') {
        if (inlineValue !== null) {
          this._fail(`argument -h/--help: ignored explicit argument '${inlineValue}'`);
        }
        this._printHelpAndExit();
      }

      if (resolved.kind === 'ambiguous') {
