      values[option.dest] = converted;
      seen.add(option.dest);
    }

    // Required-but-missing check (declaration order).
    const missing = [];
    for (const opt of this._options) {
      if (opt.required && !seen.has(opt.dest)) {
        missing.push(opt.name);
      }
    }
    if (missing.length > 0) {
      this._fail('the following arguments are required: ' + missing.join(', '));
    }

    if (extras.length > 0) {
      this._fail('unrecognized arguments: ' + extras.join(' '));
    }

    return values;
  }
